// Extract keywords from feature brief
function extractKeywords(text) {
  // Convert to lowercase and remove punctuation
  const cleaned = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');

  // Split into words and filter out common stop words
  const stopWords = new Set(['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'from', 'as', 'is', 'was', 'are', 'be', 'been', 'being', 'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'should', 'could', 'may', 'might', 'can', 'this', 'that', 'these', 'those', 'it', 'its', 'we', 'our', 'you', 'your', 'they', 'their']);

  const words = cleaned.split(/\s+/).filter(word => 
    word.length > 2 && !stopWords.has(word)
  );

  // Count word frequency
  const frequency = {};
  words.forEach(word => {
    frequency[word] = (frequency[word] || 0) + 1;
  });

  return frequency;
}

// Score each document section by keyword matches
function scoreDocument(doc, keywords) {
  let score = 0;

  // Check keywords in doc's keyword array
  doc.keywords.forEach(docKeyword => {
    if (keywords[docKeyword]) {
      score += keywords[docKeyword] * 2; // Weight matches in predefined keywords higher
    }
  });

  // Check keywords in doc content and title
  const docText = (doc.title + ' ' + doc.content).toLowerCase();
  Object.keys(keywords).forEach(keyword => {
    const regex = new RegExp('\\b' + keyword + '\\b', 'g');
    const matches = docText.match(regex);
    if (matches) {
      score += matches.length * keywords[keyword];
    }
  });

  return score;
}

