// Helper function to check if text contains testable conditions
function isTestable(criteriaText) {
  const testablePatterns = [
    /given.*when.*then/i,
    /should|must|will|can/i,
    /verify|validate|check|ensure/i,
    /displays?|shows?|returns?|creates?|updates?|deletes?/i
  ];
  return testablePatterns.some(pattern => pattern.test(criteriaText));
}

// Helper function to check for hallucinated systems
function checkForHallucinatedSystems(text) {
  const suspiciousPatterns = [
    /\b[A-Z][a-zA-Z]*\s+(API|Service|System|Database|Engine|Platform)\b/g
  ];

  const foundSystems = [];
  suspiciousPatterns.forEach(pattern => {
    const matches = text.match(pattern);
    if (matches) {
      matches.forEach(match => {
        const normalized = match.trim();
        const isKnown = knownSlackSystems.some(known => 
          normalized.toLowerCase().includes(known.toLowerCase()) ||
          known.toLowerCase().includes(normalized.toLowerCase())
        );
        if (!isKnown) {
          foundSystems.push(normalized);
        }
      });
    }
  });

  return foundSystems;
}

